// Klyvaron Lite inference in the core service, checked against NumPy.
//
// The interesting assertion here is not "the code runs" -- it is that this JavaScript
// forward pass produces the same logits as the Python one on the same bytes. That is
// checked against a committed fixture generated by `services/fabric/scripts/export_lm.py
// --parity-fixture`, which carries the exact float32 weights, the reference logits
// computed by NumPy, and the greedy continuation NumPy produced. If someone changes an
// activation, the attention scale or the output projection here, these tests fail
// instead of shipping a model that runs and is subtly wrong.
//
// The rest of the file is the negative half: a manifest and an archive that disagree
// must be refused, because a loader that accepts a mismatched checkpoint does not throw
// -- it generates worse text, and the model gets blamed.

import test from 'node:test'
import assert from 'node:assert/strict'
import { mkdtempSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'

import {
  ArtifactError, loadArtifact, parameterCount, readNpz, validateManifest, vocabularyDigest,
} from '../src/klyvaron/format.mjs'
import { KlyvaronRuntime } from '../src/klyvaron/runtime.mjs'
import { KlyvaronProvider } from '../src/providers/klyvaron.mjs'
import { OPERATIONS } from '../src/providers/base.mjs'
import { AVAILABILITY } from '../src/router/registry.mjs'

const FIXTURE_PATH = new URL('./fixtures/klyvaron-lite-parity.json', import.meta.url)
const fixture = JSON.parse(readFileSync(FIXTURE_PATH, 'utf8'))

const decodeArray = (entry) => {
  const bytes = Buffer.from(entry.base64, 'base64')
  assert.equal(bytes.length, entry.shape.reduce((a, b) => a * b, 1) * 4, 'the fixture array must hold float32 values')
  return Float32Array.from(new Float32Array(bytes.buffer, bytes.byteOffset, bytes.length / 4))
}

/** The artifact the fixture describes, assembled in memory. */
function fixtureArtifact() {
  const weights = new Map()
  for (const [name, entry] of Object.entries(fixture.weights)) {
    weights.set(name, { shape: entry.shape, dtype: entry.dtype, data: decodeArray(entry) })
  }
  return {
    manifest: fixture.manifest,
    weights,
    directory: '(fixture)',
    manifestPath: null,
    weightsPath: null,
    sha256: fixture.manifest.weights.sha256,
  }
}

const closeEnough = (a, b, tolerance, message) => {
  assert.ok(Math.abs(a - b) <= tolerance, `${message}: ${a} vs ${b} (tolerance ${tolerance})`)
}

test('the fixture describes a small artifact, not a released model', () => {
  assert.equal(fixture.format, 'klyvaron.parity-fixture/1')
  assert.equal(fixture.manifest.instructionTuned, false)
  assert.equal(fixture.manifest.provenance.origin, 'test_fixture')
  assert.ok(fixture.manifest.limitations.length >= 1, 'even a fixture declares its limitations')
  assert.ok(fixture.manifest.provenance.parameterCount < 20_000, 'the fixture must stay small enough to commit')
})

test('the JavaScript vocabulary digest equals the Python one', () => {
  // Same specification, two implementations. If this fails, every artifact exported by
  // services/fabric is rejected by the loader, which is exactly the failure the digest
  // formula exists to make loud.
  assert.equal(vocabularyDigest(fixture.manifest.tokenizer.characters), fixture.manifest.tokenizer.digest)
  // And the digest is sensitive to a single character, not just to the length.
  const mutated = [...fixture.manifest.tokenizer.characters]
  mutated[0] = mutated[0] === 'x' ? 'y' : 'x'
  assert.notEqual(vocabularyDigest(mutated), fixture.manifest.tokenizer.digest)
})

test('the manifest validates, and its parameter count matches the architecture', () => {
  assert.doesNotThrow(() => validateManifest(fixture.manifest))
  assert.equal(parameterCount(fixture.manifest.architecture), fixture.manifest.provenance.parameterCount)
})

test('the .npz reader reads real NumPy archives byte for byte', () => {
  const arrays = readNpz(Buffer.from(fixture.npzBase64, 'base64'))
  assert.equal(arrays.size, Object.keys(fixture.weights).length)
  for (const [name, entry] of Object.entries(fixture.weights)) {
    const read = arrays.get(name)
    assert.ok(read, `'${name}' must be present in the archive`)
    assert.deepEqual(read.shape, entry.shape)
    const expected = decodeArray(entry)
    assert.equal(read.data.length, expected.length)
    for (let i = 0; i < expected.length; i += 1) {
      assert.equal(read.data[i], expected[i], `'${name}' differs at index ${i}`)
    }
  }
})

test('the runtime reproduces NumPy logits, and its greedy continuation is identical', () => {
  const runtime = new KlyvaronRuntime(fixtureArtifact())
  assert.equal(runtime.parameterCount, fixture.manifest.provenance.parameterCount)

  for (const testCase of fixture.cases) {
    const ids = Int32Array.from(testCase.tokenIds)
    const logits = runtime.logits(ids)
    assert.equal(logits.length, fixture.manifest.architecture.vocab_size)
    // float32 storage against float64 accumulation: agreement is close, not bit-exact.
    // The fixture records the gap between the top two logits so this test can prove the
    // comparison is meaningful rather than merely loose.
    for (let i = 0; i < logits.length; i += 1) {
      closeEnough(logits[i], testCase.logits[i], 1e-3, `logits[${i}] for ${JSON.stringify(testCase.prompt)}`)
    }
    assert.ok(testCase.topGap > 1e-2, 'a near-tie would make greedy agreement luck rather than evidence')
    const best = logits.indexOf(Math.max(...logits))
    const referenceBest = testCase.logits.indexOf(Math.max(...testCase.logits))
    assert.equal(best, referenceBest, 'the argmax must agree, or greedy decoding diverges immediately')
  }

  for (const greedy of fixture.greedy) {
    const result = runtime.generate({ prompt: greedy.prompt, maxNewTokens: greedy.maxNewTokens, temperature: 0 })
    assert.equal(result.text, greedy.text, `greedy continuation of ${JSON.stringify(greedy.prompt)} must match NumPy`)
    assert.equal(result.stoppedBy, 'length')
    assert.equal(result.generatedTokens, greedy.maxNewTokens)
  }
})

test('generation is clamped to the manifest and the context, and reports its stopping reason', () => {
  const runtime = new KlyvaronRuntime(fixtureArtifact())
  const ceiling = fixture.manifest.generation.maxNewTokens
  const over = runtime.generate({ prompt: 'Aetheris', maxNewTokens: 10_000, temperature: 0 })
  assert.equal(over.generatedTokens, Math.min(ceiling, runtime.contextTokens))

  const stopped = runtime.generate({ prompt: 'Aetheris', maxNewTokens: 32, temperature: 0, stop: [over.text.slice(0, 3)] })
  assert.equal(stopped.stoppedBy, 'stop')
  assert.ok(!stopped.text.endsWith(over.text.slice(0, 3)), 'the stop sequence must not remain in the output')

  const cancelled = new AbortController()
  cancelled.abort()
  assert.equal(runtime.generate({ prompt: 'Aetheris', temperature: 0, signal: cancelled.signal }).stoppedBy, 'cancelled')
})

test('a tampered manifest is refused, field by field', () => {
  const clone = () => JSON.parse(JSON.stringify(fixture.manifest))
  const cases = [
    ['a missing limitation', (m) => { m.limitations = [] }, /at least one limitation/],
    ['an architecture/weight disagreement', (m) => { m.architecture.n_layers += 1 }, /disagree/],
    ['a changed vocabulary', (m) => { m.tokenizer.characters[0] = 'Z' }, /digest|duplicate/i],
    ['a vocabulary length that contradicts the architecture', (m) => { m.architecture.vocab_size += 1 }, /vocabulary has/],
    ['an unknown format', (m) => { m.format = 'klyvaron.artifact/2' }, /unsupported artifact format/],
    ['an instruction claim', (m) => { m.instructionTuned = 'yes' }, /boolean/],
  ]
  for (const [label, mutate, pattern] of cases) {
    const manifest = clone()
    mutate(manifest)
    assert.throws(() => validateManifest(manifest), (error) => {
      assert.ok(error instanceof ArtifactError, `${label} must raise an ArtifactError`)
      assert.match(error.message, pattern, `${label}: ${error.message}`)
      return true
    }, label)
  }
})

test('loading from a directory verifies the bytes, and a corrupted file is refused', () => {
  const directory = mkdtempSync(join(tmpdir(), 'klyvaron-artifact-'))
  writeFileSync(join(directory, 'parity.npz'), Buffer.from(fixture.npzBase64, 'base64'))
  writeFileSync(join(directory, 'klyvaron-parity-tiny.klyvaron.json'), JSON.stringify(fixture.manifest, null, 2))

  const loaded = loadArtifact(directory)
  assert.equal(loaded.sha256, fixture.manifest.weights.sha256)
  assert.equal(loaded.weights.size, Object.keys(fixture.weights).length)

  // Flip one byte in the middle of the archive: the size still matches, the digest does not.
  const bytes = readFileSync(join(directory, 'parity.npz'))
  bytes[Math.floor(bytes.length / 2)] ^= 0xff
  writeFileSync(join(directory, 'parity.npz'), bytes)
  assert.throws(() => loadArtifact(directory), (error) => {
    assert.equal(error.code, 'digest_mismatch')
    return true
  })

  // A manifest naming a file that is not there is a different, equally loud failure.
  mkdirSync(join(directory, 'empty'))
  writeFileSync(join(directory, 'empty', 'x.klyvaron.json'), JSON.stringify({ ...fixture.manifest, weights: { ...fixture.manifest.weights, file: 'gone.npz' } }))
  assert.throws(() => loadArtifact(join(directory, 'empty')), (error) => {
    assert.equal(error.code, 'weights_missing')
    return true
  })
})

test('the provider answers honestly about a base model', async () => {
  const runtime = new KlyvaronRuntime(fixtureArtifact())
  const provider = new KlyvaronProvider({ runtime, guard: { fetch: () => { throw new Error('the Klyvaron provider must never reach the network') } } })

  assert.deepEqual(KlyvaronProvider.operations, [OPERATIONS.CHAT, OPERATIONS.CHAT_STREAM])
  const probe = await provider.probe()
  assert.equal(probe.availability, AVAILABILITY.READY)
  assert.equal(probe.detail.instructionTuned, false)

  const response = await provider.chat({ messages: [{ role: 'user', content: 'Aetheris' }], maxTokens: 8 })
  assert.equal(response.instructionTuned, false)
  assert.match(response.limitation, /does not follow instructions/)
  assert.equal(response.usage.completionTokens, 8)
  assert.equal(response.doneReason, 'length')

  // The descriptor carries the artifact's own limitations, not a summary of them.
  assert.deepEqual(provider.safeDescriptor().limitations, fixture.manifest.limitations)
  assert.ok(provider.measurement().meanTokensPerSecond > 0, 'a speed claim needs a measurement behind it')

  const chunks = []
  for await (const chunk of provider.chatStream({ messages: [{ role: 'user', content: 'Aetheris' }], maxTokens: 4 })) chunks.push(chunk)
  assert.equal(chunks.join(''), (await provider.chat({ messages: [{ role: 'user', content: 'Aetheris' }], maxTokens: 4 })).text)

  await assert.rejects(() => provider.chat({ messages: [{ role: 'user', content: '   ' }] }), /prompt is required/)
})
